async function refreshPrivacySurfaces({ balance = false } = {}) {
  const tasks = [
    refreshEvents(),
    refreshAuditorTransfers(),
    scanKeplrNotes({ quiet: true }),
    refreshNotes(),
    refreshProtocolStatus()
  ];
  if (balance) {
    tasks.unshift(refreshWalletBalance());
  }
  await Promise.allSettled(tasks);
}
